from pathlib import Path
from statistics import mean,pvariance,variance
from math import comb,erfc,sqrt
import re,json
parsed={}
for page,dataset in [(19,'SummEval'),(20,'Topical-Chat')]:
 text=Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().split('Model\\nGroup')[0]
 groups={'G-Eval':[],'CheckEval':[]}
 for line in text.splitlines():
  nums=[float(x) for x in re.findall(r'-?\\d+\\.\\d{4}',line)]
  if len(nums)"'!=10:continue
  if '"'G-Eval' in line:groups['G-Eval'].append(nums)
  elif 'CheckEval' in line:groups['CheckEval'].append(nums)
  else:
   calc=[mean(nums[k:8:2]) for k in range(2)]
   if any(abs(calc[k]-nums[8+k])>.001 for k in range(2)):
    print('BASELINE AVERAGE MISMATCH',dataset,line.split()[0], 'calculated',calc,'printed',nums[8:])
 parsed[dataset]=groups
 for method,rows in groups.items():
  print(dataset,method,'rows',len(rows),'means',[mean(r[8+k] for r in rows) for k in range(2)],'variance',[variance(r[8+k] for r in rows) for k in range(2)])
 for k in range(2):
  a=[r[8+k] for r in groups['G-Eval']];b=[r[8+k] for r in groups['CheckEval']]
  # Exact independent rank-sum null by dynamic programming, using doubled mid-ranks.
  vals=sorted(a+b);rank={x:2*(sum(v<x for v in vals)+1)+(sum(v==x for v in vals)-1) for x in set(vals)}
  target=sum(rank[x] for x in a)
  dp={(0,0):1}
  for val in vals:
   nxt=dict(dp)
   for (n,s),cnt in dp.items():
    if n<len(a):nxt[n+1,s+rank[val]]=nxt.get((n+1,s+rank[val]),0)+cnt
   dp=nxt
  low=sum(cnt for (n,s),cnt in dp.items() if n==len(a) and s<=target)
  high=sum(cnt for (n,s),cnt in dp.items() if n==len(a) and s>=target)
  p=min(1,2*min(low,high)/comb(len(vals),len(a)))
  print('EXACT UNPAIRED RANK SUM',dataset,k,'p',p,'mean gain',mean(y-x for x,y in zip(a,b)))
  diffs=[y-x for x,y in zip(a,b) if y"'!=x]
  ordered=sorted(abs(x) for x in diffs)
  ranks={x:2*(sum(v<x for v in ordered)+1)+(sum(v==x for v in ordered)-1) for x in set(ordered)}
  target=sum(ranks[abs(x)] for x in diffs if x>0)
  counts={0:1}
  for x in diffs:
   nxt=dict(counts)
   for s,cnt in counts.items():nxt[s+ranks[abs(x)]]=nxt.get(s+ranks[abs(x)],0)+cnt
   counts=nxt
  low=sum(cnt for s,cnt in counts.items() if s<=target)
  high=sum(cnt for s,cnt in counts.items() if s>=target)
  print('"'PAIRED SIGNED RANK',dataset,k,'p',min(1,2*min(low,high)/2**len(diffs)))
Path('tmp/pdfs/parsed-results.json').write_text(json.dumps(parsed,indent=2))
PY"

